  Meshping — github.com/Svedrin/meshping




{[ layout_json | safe ]}

(function () {
  "use strict";

  var svg = document.getElementById("network-svg");
  var dataEl = document.getElementById("layout-data");
  var LAYOUT = JSON.parse(dataEl.textContent);
  var TREE       = LAYOUT.tree;        // node id -> [child id, ...]
  var COL_W      = LAYOUT.colW;
  var H_GAP      = LAYOUT.hGap;
  var PAD_X      = LAYOUT.padX;
  var CANVAS_W_MIN = LAYOUT.canvasWMin;

  var collapsed = {};   // node id -> true, for nodes the user collapsed

  // Assign each visible node a fractional column index, exactly mirroring
  // the server-side layout algorithm, but treating collapsed nodes as leaves.
  function assignColumns(root) {
    var leafCounter = 0;
    var xcol = {};
    function visit(node) {
      var children = collapsed[node] ? [] : (TREE[node] || []);
      if (!children.length) {
        xcol[node] = leafCounter + 0.5;
        leafCounter += 1;
      } else {
        for (var i = 0; i < children.length; i++) {
          visit(children[i]);
        }
        xcol[node] = (xcol[children[0]] + xcol[children[children.length - 1]]) / 2;
      }
    }
    visit(root);
    return { xcol: xcol, leaves: Math.max(leafCounter, 1) };
  }

  function relayout() {
    var res   = assignColumns("SELF");
    var xcol  = res.xcol;
    var leaves = res.leaves;
    var treeSpan = leaves * COL_W - H_GAP;
    var canvasW  = Math.max(CANVAS_W_MIN, Math.round(leaves * COL_W - H_GAP + 2 * PAD_X));
    var colOffset = PAD_X + (canvasW - 2 * PAD_X - treeSpan) / 2;

    var px = {};
    for (var id in xcol) {
      px[id] = colOffset + xcol[id] * COL_W;
    }

    var nodes = svg.querySelectorAll(".node");
    for (var i = 0; i < nodes.length; i++) {
      var g  = nodes[i];
      var id2 = g.getAttribute("data-id");
      if (Object.prototype.hasOwnProperty.call(px, id2)) {
        g.style.display = "";
        var dx = px[id2] - parseFloat(g.getAttribute("data-cx"));
        g.setAttribute("transform", "translate(" + dx.toFixed(2) + ",0)");
        var label = g.querySelector(".collapse-icon-label");
        if (label) {
          label.textContent = collapsed[id2] ? g.getAttribute("data-descendants") : "−";
        }
      } else {
        g.style.display = "none";
      }
    }

    var edges = svg.querySelectorAll(".edge");
    for (var j = 0; j < edges.length; j++) {
      var p   = edges[j];
      var src = p.getAttribute("data-src");
      var tgt = p.getAttribute("data-tgt");
      if (Object.prototype.hasOwnProperty.call(px, src) && Object.prototype.hasOwnProperty.call(px, tgt)) {
        p.style.display = "";
        var x1 = px[src].toFixed(2);
        var x2 = px[tgt].toFixed(2);
        var y1  = p.getAttribute("data-y1");
        var cy1 = p.getAttribute("data-cy1");
        var cy2 = p.getAttribute("data-cy2");
        var y2  = p.getAttribute("data-y2");
        p.setAttribute("d", "M " + x1 + " " + y1 + " C " + x1 + " " + cy1 + ", " + x2 + " " + cy2 + ", " + x2 + " " + y2);
      } else {
        p.style.display = "none";
      }
    }

    svg.setAttribute("width", canvasW);
    var vb = svg.getAttribute("viewBox").split(" ");
    svg.setAttribute("viewBox", "0 0 " + canvasW + " " + vb[3]);

    ["bg-grad-rect", "bg-dots-rect", "titlebar-rect"].forEach(function (elId) {
      var el = document.getElementById(elId);
      if (el) el.setAttribute("width", canvasW);
    });
    var rule = document.getElementById("titlebar-rule");
    if (rule) rule.setAttribute("x2", canvasW);
    var titleEl = document.getElementById("title-text");
    if (titleEl) titleEl.setAttribute("x", canvasW / 2);
    var subEl = document.getElementById("subtitle-text");
    if (subEl) subEl.setAttribute("x", canvasW / 2);
    var footEl = document.getElementById("footer-text");
    if (footEl) footEl.setAttribute("x", canvasW - 12);
  }

  svg.addEventListener("click", function (ev) {
    var icon = ev.target.closest && ev.target.closest(".collapse-icon");
    if (!icon) return;
    ev.preventDefault();
    ev.stopPropagation();
    var g = icon.closest(".node");
    var id = g.getAttribute("data-id");
    if (collapsed[id]) {
      delete collapsed[id];
    } else {
      collapsed[id] = true;
    }
    relayout();
  });

  relayout();
})();
